<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Saltwind Dockyard — a three.js tactical FPS</title>
<style>
  /* Look plan: dusk harbour — cold blue air, warm rust, one signal orange. */
  :root {
    --sky: #1c2436;
    --surface: #232b3a;
    --hairline: #39445a;
    --ink: #e8e2d4;
    --muted: #8b94a0;
    --accent: #ff9a3c;
    --ally: #57b8a2;
    --enemy: #e4572e;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--sky);
    color: var(--ink);
    font-family: var(--font-ui);
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; }
  #crosshair i:nth-child(1) { left: 10px; top: 0; width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 10px; bottom: 0; width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 10px; left: 0; height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 10px; right: 0; height: 2px; width: 7px; }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  #ammo {
    position: fixed;
    right: 32px;
    bottom: 24px;
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-family: var(--font-readout);
    font-size: 56px;
    line-height: 1;
    letter-spacing: -0.03em;
    color: var(--ink);
  }
  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-reserve { font-size: 16px; color: var(--muted); }
  #weapon-name {
    position: fixed;
    right: 32px;
    bottom: 92px;
    font-family: var(--font-readout);
    font-size: 13px;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--muted);
    text-align: right;
  }

  #vitals {
    position: fixed;
    left: 32px;
    bottom: 24px;
    font-family: var(--font-readout);
    font-size: 14px;
    color: var(--muted);
    display: grid;
    gap: 4px;
  }
  #vitals b { color: var(--ink); font-weight: 500; }
  #health-bar { width: 180px; height: 6px; background: var(--hairline); border-radius: 3px; overflow: hidden; }
  #health-fill { height: 100%; width: 100%; background: var(--ally); }
  #health-fill.low { background: var(--enemy); }

  /* Top centre: round score + timer. */
  #match {
    position: fixed;
    top: 16px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 12px;
    font-family: var(--font-readout);
    font-size: 15px;
  }
  #match .team { display: flex; align-items: center; gap: 6px; }
  #match .team .dot { width: 10px; height: 10px; border-radius: 50%; }
  #match .dot.ally { background: var(--ally); }
  #match .dot.enemy { background: var(--enemy); }
  #match .score { font-size: 22px; }
  #timer { min-width: 52px; text-align: center; font-size: 20px; }
  #timer.planted { color: var(--accent); }

  /* Rosters, left and right edges. */
  .roster {
    position: fixed;
    top: 64px;
    font-family: var(--font-readout);
    font-size: 12px;
    color: var(--muted);
    display: grid;
    gap: 3px;
  }
  #roster-ally { left: 32px; }
  #roster-enemy { right: 32px; text-align: right; }
  .roster .dead { text-decoration: line-through; opacity: .45; }
  .roster .you { color: var(--ink); }

  /* Kill feed, top right under the roster. */
  #feed {
    position: fixed;
    top: 170px;
    right: 32px;
    display: grid;
    gap: 4px;
    justify-items: end;
    font-family: var(--font-readout);
    font-size: 12px;
    color: var(--muted);
  }
  #feed b { color: var(--ink); font-weight: 500; }
  #feed .kill-enemy { color: var(--enemy); }

  /* Centre banner for round messages. */
  #banner {
    position: fixed;
    top: 22%;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    font-size: 30px;
    font-weight: 500;
    letter-spacing: -0.02em;
    text-shadow: 0 2px 12px rgba(0,0,0,.6);
  }
  #banner small {
    display: block;
    margin-top: 6px;
    font-size: 15px;
    font-weight: 400;
    color: var(--muted);
  }
  #banner[hidden] { display: none; }

  /* Plant / defuse progress. */
  #channel {
    position: fixed;
    left: 50%;
    top: 58%;
    transform: translateX(-50%);
    width: 260px;
    text-align: center;
    font-family: var(--font-readout);
    font-size: 13px;
  }
  #channel[hidden] { display: none; }
  #channel-bar { height: 6px; margin-top: 6px; background: var(--hairline); border-radius: 3px; overflow: hidden; }
  #channel-fill { height: 100%; width: 0; background: var(--accent); }

  .overlay {
    position: fixed;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 24px;
    background: color-mix(in srgb, var(--sky) 82%, transparent);
  }
  .overlay[hidden] { display: none; }
  .panel {
    width: min(460px, 100%);
    padding: 32px;
    background: var(--surface);
    border: 1px solid var(--hairline);
    border-radius: var(--radius-panel);
  }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 500; letter-spacing: -0.02em; }
  .panel p { margin: 0 0 24px; max-width: 46ch; font-size: 16px; line-height: 1.5; color: var(--muted); }
  .panel .row { display: flex; gap: 12px; align-items: baseline; font-family: var(--font-readout); font-size: 14px; color: var(--muted); }
  .panel .row b { color: var(--ink); font-weight: 500; font-size: 20px; }
  #play {
    font: inherit;
    font-weight: 500;
    padding: 12px 16px;
    border: 1px solid var(--accent);
    border-radius: var(--radius-control);
    background: var(--accent);
    color: var(--sky);
    cursor: pointer;
  }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; }
  .keys kbd {
    min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: var(--radius-panel);
    font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center;
  }

  /* Buy menu. */
  #buy {
    position: fixed;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 24px;
    background: color-mix(in srgb, var(--sky) 72%, transparent);
    pointer-events: auto;
  }
  #buy[hidden] { display: none; }
  #buy .panel { width: min(560px, 100%); }
  #buy table { width: 100%; border-collapse: collapse; font-size: 15px; }
  #buy td, #buy th { padding: 8px 4px; border-bottom: 1px solid var(--hairline); text-align: left; }
  #buy th { font-family: var(--font-readout); font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
  #buy td.price { font-family: var(--font-readout); text-align: right; color: var(--accent); }
  #buy td.key { font-family: var(--font-readout); color: var(--muted); width: 28px; }
  #buy tr.owned td { color: var(--ally); }
  #buy tr.cant td { opacity: .45; }
  #buy .money { font-family: var(--font-readout); font-size: 18px; margin-bottom: 12px; }
  #buy .money b { color: var(--accent); font-weight: 500; }
  #buy .hint { margin-top: 16px; font-size: 13px; color: var(--muted); }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #play { transition-duration: 0.01ms; }
  }
</style>
</head>
